1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives an owner's {@code identityKey}: the single value duplicate detection is expressed
12	 * through. It is the SHA-256 hex digest of {@code normalizedTelephone + '|' + (email or empty) +
13	 * '|' + soundex(lastName)}, where the telephone is E.164 (see {@link E164Telephone}), the email is
14	 * lower-cased (empty when absent) and the last name is reduced to its {@link Soundex} code. Because
15	 * the telephone is part of the key, two members of one household with different telephones have
16	 * different keys and are both allowed; only owners that collide on the key are duplicates.
17	 */
18	public final class IdentityKey {
19	
20	    private IdentityKey() {
21	    }
22	
23	    public static String of(Owner owner) {
24	        return sha256Hex(telephone(owner) + '|' + email(owner) + '|' + Soundex.of(owner.getLastName()));
25	    }
26	
27	    static String telephone(Owner owner) {
28	        String telephone = E164Telephone.toE164(owner.getTelephone());
29	        return telephone == null ? "" : telephone;
30	    }
31	
32	    static String email(Owner owner) {
33	        String email = owner.getEmail();
34	        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
35	    }
36	
37	    private static String sha256Hex(String value) {
38	        try {
39	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
40	            StringBuilder hex = new StringBuilder(64);
41	            for (byte b : digest) {
42	                hex.append(String.format("%02x", b));
43	            }
44	            return hex.toString();
45	        }
46	        catch (NoSuchAlgorithmException ex) {
47	            throw new IllegalStateException(ex);
48	        }
49	    }
50	}
