1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives the stable identifier of an owner's household: the first 12 hex characters of SHA-256 over
12	 * {@code normalizedLastName + '|' + postcode} (last name compared case-insensitively with collapsed
13	 * whitespace, exactly as {@link RejectDuplicateOwnerHousehold} groups them). Every owner sharing a
14	 * last name and postcode therefore maps to the same value without any stored state, so a household
15	 * is keyed on {@code (lastName, postcode)} alone.
16	 */
17	public final class HouseholdId {
18	
19	    private HouseholdId() {
20	    }
21	
22	    public static String of(Owner owner) {
23	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
24	        String key = normalize(owner.getLastName()) + '|' + postcode;
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
27	            StringBuilder id = new StringBuilder(12);
28	            for (int i = 0; i < 6; i++) {
29	                id.append(String.format("%02X", digest[i]));
30	            }
31	            return id.toString();
32	        }
33	        catch (NoSuchAlgorithmException ex) {
34	            throw new IllegalStateException(ex);
35	        }
36	    }
37	
38	    private static String normalize(String value) {
39	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
40	    }
41	}
