2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Counts the members of an owner's household: the owners sharing this owner's {@link HouseholdId}
8	 * (last name and postcode). The owner itself is included, so a freshly created owner counts towards
9	 * its own household total.
10	 */
11	public final class HouseholdSize {
12	
13	    private HouseholdSize() {
14	    }
15	
16	    public static int of(Owner owner, OwnerRepository repository) {
17	        String householdId = HouseholdId.of(owner);
18	        int count = 0;
19	        for (Owner other : repository.findAll()) {
20	            if (householdId.equals(HouseholdId.of(other))) {
21	                count++;
22	            }
23	        }
24	        return count;
25	    }
26	}
