1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	
5	/**
6	 * Derives an owner's segment formatted {@code <TIER>_<AREA>}: TIER is {@code PREMIUM} when the
7	 * membership level is 3 or more, otherwise {@code STANDARD}; AREA is {@code METRO} for a known
8	 * region (NSW, VIC or QLD), otherwise {@code REGIONAL}.
9	 */
10	public final class OwnerSegment {
11	
12	    private static final Set<String> KNOWN_REGIONS = Set.of("NSW", "VIC", "QLD");
13	
14	    private OwnerSegment() {
15	    }
16	
17	    public static String of(int membershipLevel, String locality) {
18	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
19	        String area = KNOWN_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
20	        return tier + "_" + area;
21	    }
22	}
