13	
14	public class RespondWithOwner {
15	
16	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
17	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
18	
19	    private static final Set<String> DISPOSABLE_DOMAINS =
20	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
21	
22	    public void service(@Val Owner owner, OwnerMapper ownerMapper, OwnerRepository ownerRepository,
23	            ObjectResponse<OwnerDto> response) {
24	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
25	        dto.setSelfLink("/api/owners/" + owner.getId());
26	        int namesakeCount = NamesakeCount.of(owner, ownerRepository);
27	        dto.setNamesakeCount(namesakeCount);
28	        int membershipPoints = MembershipPoints.of(owner, namesakeCount, HouseholdSize.of(owner, ownerRepository));
29	        dto.setMembershipPoints(membershipPoints);
30	        dto.setMembershipLevel(HouseholdLevelCeiling.cap(owner, MembershipLevel.of(membershipPoints), ownerRepository));
31	        dto.setLocality(Locality.of(owner));
32	        dto.setTimezone(REGION_TIMEZONE.get(dto.getLocality()));
33	        dto.setOwnerSegment(OwnerSegment.of(dto.getMembershipLevel(), dto.getLocality()));
34	        dto.setBulkSignupWarning(BulkSignupWarning.of(owner, ownerRepository));
35	        dto.setCapacityWarning(CapacityWarning.of(owner, ownerRepository));
36	        dto.setContactPreference(ContactPreference.of(owner));
37	        Integer possibleDuplicateOf = PossibleDuplicate.of(owner, ownerRepository);
38	        dto.setPossibleDuplicate(possibleDuplicateOf != null);
39	        dto.setPossibleDuplicateOf(possibleDuplicateOf);
40	        dto.setRiskFlag(possibleDuplicateOf != null || Boolean.TRUE.equals(dto.getCapacityWarning())
41	                || disposableAdjacent(owner.getEmail()));
42	        response.send(dto);
43	    }
44	
45	    /** A domain is disposable-adjacent when it is a known disposable domain or a subdomain of one. */
46	    private static boolean disposableAdjacent(String email) {
47	        if (email == null || email.isBlank()) {
48	            return false;
49	        }
50	        String domain = email.substring(email.lastIndexOf('@') + 1).toLowerCase(Locale.ROOT);
51	        return DISPOSABLE_DOMAINS.stream().anyMatch(d -> domain.equals(d) || domain.endsWith("." + d));
52	    }
53	}
