1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * American Soundex code of a name: its first letter followed by three digits derived from the
7	 * remaining consonants (like-sounding letters share a digit; vowels and repeats drop out, {@code H}
8	 * and {@code W} never separate), padded with zeros to four characters. A null or letterless name
9	 * yields {@code "0000"}. Used both inside the {@link IdentityKey} and by {@link PossibleDuplicate},
10	 * so last names that merely sound alike are grouped identically in each.
11	 */
12	public final class Soundex {
13	
14	    private static final String DIGITS = "01230120022455012623010202";
15	
16	    private Soundex() {
17	    }
18	
19	    public static String of(String name) {
20	        String letters = name == null ? "" : name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
21	        if (letters.isEmpty()) {
22	            return "0000";
23	        }
24	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
25	        char previous = digit(letters.charAt(0));
26	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
27	            char c = letters.charAt(i);
28	            char d = digit(c);
29	            if (d != '0' && d != previous) {
30	                code.append(d);
31	            }
32	            if (c != 'H' && c != 'W') {
33	                previous = d;
34	            }
35	        }
36	        while (code.length() < 4) {
37	            code.append('0');
38	        }
39	        return code.toString();
40	    }
41	
42	    private static char digit(char c) {
43	        return DIGITS.charAt(c - 'A');
44	    }
45	}
