1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's unified {@code memberId} formatted {@code <REGION><FY><HASH8><CHK>}: REGION is
12	 * the region code (see {@link Locality}), FY is the 2-digit fiscal year (see {@link FiscalYear}),
13	 * HASH8 is the first 8 upper-case hex characters of SHA-256 over the normalized telephone followed
14	 * by the last name, and CHK is the single Luhn check digit (see {@link CheckDigit}) over the digits
15	 * of {@code <REGION><FY><HASH8>} (e.g. 'NSW271A2B3C4D5'). Stored in the {@code customerCode} slot,
16	 * so downstream deduplication, the create audit record and the response all read this identity.
17	 */
18	public class AssignOwnerCustomerCode {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setCustomerCode(Locality.of(owner) + FiscalYear.yy(owner) + hash8(owner));
22	        owner.setCustomerCode(owner.getCustomerCode() + CheckDigit.of(owner));
23	    }
24	
25	    private static String hash8(Owner owner) {
26	        String key = owner.getTelephone() + owner.getLastName();
27	        try {
28	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
29	            StringBuilder hash = new StringBuilder(8);
30	            for (int i = 0; i < 4; i++) {
31	                hash.append(String.format("%02X", digest[i]));
32	            }
33	            return hash.toString();
34	        }
35	        catch (NoSuchAlgorithmException ex) {
36	            throw new IllegalStateException(ex);
37	        }
38	    }
39	}
