1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerIdentityException;
7	
8	/**
9	 * Rejects 409 when the built owner shares another owner's {@link HouseholdId} — that is, another
10	 * owner already exists with the same last name and postcode. Opting in with {@code sharesHousehold}
11	 * bypasses this block: the owner is then created as a declared household member (and, being
12	 * declared, is not later flagged as a possible duplicate).
13	 */
14	public class RejectDuplicateOwnerHousehold {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
17	            throws DuplicateOwnerIdentityException {
18	        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
19	            return;
20	        }
21	        String householdId = HouseholdId.of(owner);
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (other != owner && !Boolean.TRUE.equals(other.getDeleted())
24	                    && householdId.equals(HouseholdId.of(other))) {
25	                throw new DuplicateOwnerIdentityException(householdId);
26	            }
27	        }
28	    }
29	}
