1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Objects;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Finds the existing owner this owner is a possible (soft) duplicate of: another owner sharing this
10	 * owner's {@link Soundex} last name and postcode but with a different {@link IdentityKey}. A shared
11	 * identity key would be a hard duplicate (rejected at create, see {@link RejectDuplicateOwnerIdentity}),
12	 * so a differing key on a like-sounding name at the same postcode is exactly the soft-match case.
13	 * Owners without a postcode never soft-match. Returns the matching owner's id (the lowest when
14	 * several match), or {@code null} when there is no possible duplicate.
15	 */
16	public final class PossibleDuplicate {
17	
18	    private PossibleDuplicate() {
19	    }
20	
21	    public static Integer of(Owner owner, OwnerRepository repository) {
22	        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
23	            return null;
24	        }
25	        String postcode = owner.getPostcode();
26	        if (postcode == null || postcode.isBlank()) {
27	            return null;
28	        }
29	        String soundex = Soundex.of(owner.getLastName());
30	        String identityKey = IdentityKey.of(owner);
31	        Integer match = null;
32	        for (Owner other : repository.findAll()) {
33	            if (!Objects.equals(other.getId(), owner.getId()) && postcode.equals(other.getPostcode())
34	                    && soundex.equals(Soundex.of(other.getLastName()))
35	                    && !identityKey.equals(IdentityKey.of(other))
36	                    && (match == null || other.getId() < match)) {
37	                match = other.getId();
38	            }
39	        }
40	        return match;
41	    }
42	}
