1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	public class SaveOwner {
13	
14	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
15	
16	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
17	
18	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        ownerRepository.save(owner);
22	        int namesakeCount = NamesakeCount.of(owner, ownerRepository);
23	        int membershipLevel = MembershipLevel.of(
24	            MembershipPoints.of(owner, namesakeCount, HouseholdSize.of(owner, ownerRepository)));
25	        String memberId = owner.getCustomerCode();
26	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
27	            owner.getId(), memberId, owner.getRegistrationDate(), membershipLevel);
28	        // Immutable structured event. Carries the owner's unified primary identifier as memberId.
29	        String event = String.format(
30	            "{\"seq\":%d,\"ownerId\":%d,\"memberId\":\"%s\",\"membershipLevel\":%d,\"event\":\"OWNER_CREATED\"}",
31	            EVENT_SEQ.incrementAndGet(), owner.getId(), memberId, membershipLevel);
32	        AUDIT.info("{}", event);
33	        NOTIFY.info("welcome ownerId={} memberId={}", owner.getId(), memberId);
34	    }
35	}
