package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives the stable identifier of an owner's household: the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode} (last name compared case-insensitively with collapsed
 * whitespace, exactly as {@link RejectDuplicateOwnerHousehold} groups them). Every owner sharing a
 * last name and postcode therefore maps to the same value without any stored state, so a household
 * is keyed on {@code (lastName, postcode)} alone.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(Owner owner) {
        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
        String key = normalize(owner.getLastName()) + '|' + postcode;
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder id = new StringBuilder(12);
            for (int i = 0; i < 6; i++) {
                id.append(String.format("%02X", digest[i]));
            }
            return id.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's {@code identityKey}: the single value duplicate detection is expressed
 * through. It is the SHA-256 hex digest of {@code normalizedTelephone + '|' + (email or empty) +
 * '|' + soundex(lastName)}, where the telephone is E.164 (see {@link E164Telephone}), the email is
 * lower-cased (empty when absent) and the last name is reduced to its {@link Soundex} code. Because
 * the telephone is part of the key, two members of one household with different telephones have
 * different keys and are both allowed; only owners that collide on the key are duplicates.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        return sha256Hex(telephone(owner) + '|' + email(owner) + '|' + Soundex.of(owner.getLastName()));
    }

    static String telephone(Owner owner) {
        String telephone = E164Telephone.toE164(owner.getTelephone());
        return telephone == null ? "" : telephone;
    }

    static String email(Owner owner) {
        String email = owner.getEmail();
        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(64);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's unified {@code memberId} formatted {@code <REGION><FY><HASH8><CHK>}: REGION is
 * the region code (see {@link Locality}), FY is the 2-digit fiscal year (see {@link FiscalYear}),
 * HASH8 is the first 8 upper-case hex characters of SHA-256 over the normalized telephone followed
 * by the last name, and CHK is the single Luhn check digit (see {@link CheckDigit}) over the digits
 * of {@code <REGION><FY><HASH8>} (e.g. 'NSW271A2B3C4D5'). Stored in the {@code customerCode} slot,
 * so downstream deduplication, the create audit record and the response all read this identity.
 */
public class AssignOwnerCustomerCode {

    public void service(@Val Owner owner) {
        owner.setCustomerCode(Locality.of(owner) + FiscalYear.yy(owner) + hash8(owner));
        owner.setCustomerCode(owner.getCustomerCode() + CheckDigit.of(owner));
    }

    private static String hash8(Owner owner) {
        String key = owner.getTelephone() + owner.getLastName();
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder hash = new StringBuilder(8);
            for (int i = 0; i < 4; i++) {
                hash.append(String.format("%02X", digest[i]));
            }
            return hash.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}

